<script setup>
import { computed,onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'; import { getProducts,getSuppliers } from '../services/data'
const suppliers=ref([]),products=ref([]),selected=ref(''),date=ref(new Date().toISOString().slice(0,10)),quantities=ref({}),deliveries=ref([]),loading=ref(true),saving=ref(false),error=ref(''),message=ref('');const supplied=computed(()=>products.value.filter(p=>p.supplier_id===selected.value));
async function load(){loading.value=true;try{[suppliers.value,products.value]=await Promise.all([getSuppliers(),getProducts()]);const {data,error:e}=await supabase.from('deliveries').select('*, suppliers(name)').order('delivery_date',{ascending:false});if(e)throw e;deliveries.value=data}catch{error.value='Dobav ni bilo mogoče naložiti.'}finally{loading.value=false}}onMounted(load)
async function save(){error.value='';const rows=supplied.value.filter(p=>Number(quantities.value[p.id])>0);if(!selected.value||!rows.length){error.value='Izberite dobavitelja in vnesite vsaj eno količino.';return}saving.value=true;try{const {data,error:e}=await supabase.from('deliveries').insert({supplier_id:selected.value,delivery_date:date.value}).select().single();if(e)throw e;const {error:i}=await supabase.from('delivery_items').insert(rows.map(p=>({delivery_id:data.id,product_id:p.id,quantity:Number(quantities.value[p.id])})));if(i)throw i;message.value='Dobava je shranjena.';quantities.value={};await load()}catch{error.value='Dobave ni bilo mogoče shraniti. Poskusite ponovno.'}finally{saving.value=false}}
</script><template><section class="page"><header><p class="eyebrow">ADMINISTRACIJA</p><h1>Dobave</h1></header><div v-if="loading" class="center-state">Nalagam dobave …</div><template v-else><form class="card stack" @submit.prevent="save"><h2>Nova dobava</h2><label>Dobavitelj<select v-model="selected"><option value="">Izberite dobavitelja</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select></label><label>Datum dobave<input v-model="date" type="date" required /></label><template v-if="selected"><label v-for="p in supplied" class="count-row"><span>{{p.name}}<small>{{p.unit}}</small></span><input v-model="quantities[p.id]" type="number" min="0" step="0.001" inputmode="decimal" /></label></template><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><button :disabled="saving">{{saving?'Shranjujem …':'Potrdi dobavo'}}</button></form><h2 class="section-title">Zgodovina dobav</h2><div v-for="d in deliveries" class="list-row"><strong>{{d.suppliers?.name}}</strong><span>{{new Date(d.delivery_date).toLocaleDateString('sl-SI')}}</span></div></template></section></template>
